//following this check marks the test as fail, because the protection is missing on this public website and seems to be some security vulnerabilieties which needs to be checked further
cy.request({
  url: 'https://www.saucedemo.com/',
  failOnStatusCode: false
}).then(response => {
  const headers = response.headers;
  const xFrameOptions = headers['x-frame-options'];
  const csp = headers['content-security-policy'];
  const hasXFrameProtection = typeof xFrameOptions === 'string' && ['deny', 'sameorigin'].includes(xFrameOptions.toLowerCase());
  const hasCspFrameProtection = typeof csp === 'string' && /frame-ancestors\s+[^;]+/i.test(csp);
  expect(hasXFrameProtection || hasCspFrameProtection, 'X-Frame-Options or CSP frame-ancestors protection').to.equal(true);
});

